from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    candidates = []
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1:
            candidates.append((counts[grid[r][0]], 'h', r))
    for c in range(1, w - 1):
        if len({grid[r][c] for r in range(h)}) == 1:
            candidates.append((counts[grid[0][c]], 'v', c))
    _, axis, sep = min(candidates)
    if axis == 'h':
        a, b = grid[:sep], grid[sep + 1:]
    else:
        a = [row[:sep] for row in grid]
        b = [row[sep + 1:] for row in grid]
    if len(a) > len(b):
        a = a[:len(b)]
    elif len(b) > len(a):
        b = b[:len(a)]
    if axis == 'h' and len(a[0]) != len(b[0]):
        width = min(len(a[0]), len(b[0]))
        a = [row[:width] for row in a]; b = [row[:width] for row in b]
    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    color = min(common, key=lambda x: counts[x])
    out = [[color for _ in range(len(a[0]))] for _ in range(len(a))]
    for r in range(len(a)):
        for c in range(len(a[0])):
            if a[r][c] == color and b[r][c] == color:
                out[r][c] = 3
    return out

